// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    // fuzzed: from address and a single recipient address and a value and a flag whether callee should revert
    function testFuzz_property(address from, address tosAddr, uint256 v, bool shouldRevert) public {
        // keep tosAddr non-zero and from non-zero so require(_tos.length>0) and addresses are valid
        vm.assume(tosAddr != address(0));
        vm.assume(from != address(0));

        // Deploy a recorder/optional-reverter that matches the selector transferFrom(address,address,uint256)
        Recorder rec = new Recorder(shouldRevert);

        // prepare single-element array of recipients; allocate on stack
        address[] memory _tos = new address[](1);
        _tos[0] = address(rec);

        // Call transfer through try/catch to observe whether it reverted or returned
        bool ok;
        try c.transfer(from, address(rec), _tos, v) returns (bool ret) {
            ok = ret; // capture returned boolean
            // When the reference contract is used, ret should be true for any successful call;
            // the mutant changes it to false even when call succeeds.
        } catch {
            // if it reverts, mark as reverted by setting ok = false and skip assertion that expects true
            ok = false;
        }

        // If the internal external calls were set to revert, then the whole transfer will revert
        // (require(_s) in loop). In that case ok==false and we cannot assert return value. We only
        // assert the universal property for successful (non-reverting) calls.
        if (!shouldRevert) {
            // For the reference implementation, any successful call to transfer returns true.
            // The mutant returns false for the same successful scenario; thus this assertion
            // passes on the reference for all inputs and will fail on the mutant for some input.
            assertTrue(ok);
        }
    }
}

// The helper that the contract c will call. It exposes the exact function selector
// transferFrom(address,address,uint256) so that C's low-level call decodes into this function.
contract Recorder {
    bool public shouldRevert;
    // record last call data for inspection if needed
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;
    uint256 public calls;

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // Matches bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        if (shouldRevert) revert("rec revert");
        lastFrom = from;
        lastTo = to;
        lastV = v;
        calls += 1;
        return true;
    }
}
